// HasProject applies the HasEdge predicate on the "project" edge.
func HasProject() predicate.VideoTask {
	return predicate.VideoTask(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ProjectTable, ProjectColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasProjectWith applies the HasEdge predicate on the "project" edge with a given conditions (other predicates).
func HasProjectWith(preds ...predicate.Project) predicate.VideoTask {
	return predicate.VideoTask(func(s *sql.Selector) {
		step := newProjectStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasItems applies the HasEdge predicate on the "items" edge.
func HasItems() predicate.VideoTask {
	return predicate.VideoTask(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ItemsTable, ItemsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasItemsWith applies the HasEdge predicate on the "items" edge with a given conditions (other predicates).
func HasItemsWith(preds ...predicate.VideoTaskItem) predicate.VideoTask {
	return predicate.VideoTask(func(s *sql.Selector) {
		step := newItemsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasInputs applies the HasEdge predicate on the "inputs" edge.
func HasInputs() predicate.VideoTask {
	return predicate.VideoTask(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, InputsTable, InputsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasInputsWith applies the HasEdge predicate on the "inputs" edge with a given conditions (other predicates).
func HasInputsWith(preds ...predicate.VideoTaskInput) predicate.VideoTask {
	return predicate.VideoTask(func(s *sql.Selector) {
		step := newInputsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VideoTask) predicate.VideoTask {
	return predicate.VideoTask(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VideoTask) predicate.VideoTask {
	return predicate.VideoTask(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VideoTask) predicate.VideoTask {
	return predicate.VideoTask(sql.NotPredicates(p))
}
